    best={src:None}; pred={}
    for u,v,t in evs:
        if tmin is not None and t<tmin: continue
        for a,b in ([(u,v)]+([(v,u)] if undirected else [])):
            if a in best:
                ba=best[a]
                if ba is None or (t>ba and t-ba<=D):
